package com.mps.operations.model; import com.mps.organization.model.Organization; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="backup_jobs") public class BackupJob {@Id private UUID id;@ManyToOne(optional=false,fetch=FetchType.LAZY) @JoinColumn(name="organization_id") private Organization organization;@Column(name="backup_type",nullable=false) private String backupType;@Column(nullable=false) private String status;@Column(name="requested_by") private UUID requestedBy;@Column(name="storage_location",length=1000) private String storageLocation;private String checksum;@Column(name="size_bytes") private Long sizeBytes;@Column(length=2000) private String message;@Column(name="requested_at",nullable=false) private Instant requestedAt;@Column(name="started_at") private Instant startedAt;@Column(name="completed_at") private Instant completedAt;protected BackupJob(){}public BackupJob(Organization o,String type,UUID actor){id=UUID.randomUUID();organization=o;backupType=type;status="REQUESTED";requestedBy=actor;requestedAt=Instant.now();}public void markQueued(String location){status="QUEUED";storageLocation=location;message="Backup request queued for the operational runner.";} public UUID getId(){return id;}public String getBackupType(){return backupType;}public String getStatus(){return status;}public String getStorageLocation(){return storageLocation;}public String getMessage(){return message;}public Instant getRequestedAt(){return requestedAt;}public Instant getStartedAt(){return startedAt;}public Instant getCompletedAt(){return completedAt;}public Long getSizeBytes(){return sizeBytes;}public String getChecksum(){return checksum;}}
